import {applyColorRules} from './art-color-core.js?v=2.17.3';
import {openGarmentComposer} from './garment-composer.js?v=2.17.3';
import {createGarmentCloudStore} from './garment-cloud-store.js?v=2.17.3';

const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=value=>Number(String(value??'').trim().replace(',','.'));
const decimal=value=>Number(value).toLocaleString('pt-BR',{maximumFractionDigits:2});
const clamp=(n,min,max)=>Math.max(min,Math.min(max,n));
const frame=()=>new Promise(resolve=>requestAnimationFrame(resolve));
const toBlob=canvas=>new Promise((resolve,reject)=>canvas.toBlob(blob=>blob?resolve(blob):reject(new Error('O navegador não conseguiu gerar o PNG.')),'image/png'));

export function shirtScale(stageWidth,shirtWidthCm){return stageWidth*.59/shirtWidthCm}
export function shirtStageRatio(widthCm,lengthCm){return (lengthCm/widthCm)*(.59/.89)}

function mountDialog(title,subtitle,content,footer,variant){
  const previous=document.activeElement,modal=document.createElement('div');modal.className='art-studio-backdrop';
  modal.innerHTML=`<section class="art-studio ${variant}" role="dialog" aria-modal="true" aria-label="${escape(title)}"><header class="art-studio-head"><div><span class="studio-eyebrow">ZERO 19 / ESTÚDIO</span><h2>${escape(title)}</h2><p>${escape(subtitle)}</p></div><button class="studio-close" aria-label="Fechar">×</button></header>${content}<footer class="art-studio-footer">${footer}</footer><div class="studio-message" aria-live="polite"></div></section>`;
  document.body.append(modal);const oldOverflow=document.body.style.overflow,controller=new AbortController();document.body.style.overflow='hidden';let busy=false,closed=false,cleanup=()=>{};
  const close=(force=false)=>{if(closed||busy&&!force)return;closed=true;window.removeEventListener('z19:account-changing',accountChanging);controller.abort();cleanup();modal.remove();document.body.style.overflow=force?'':oldOverflow;if(!force&&previous?.isConnected)previous.focus()};
  const accountChanging=()=>close(true);window.addEventListener('z19:account-changing',accountChanging);
  modal.querySelector('.studio-close').onclick=()=>close();
  modal.addEventListener('keydown',event=>{if(event.key==='Escape'){event.stopPropagation();close()}if(event.key==='Tab'){const controls=[...modal.querySelectorAll('button,input,select,[tabindex="0"]')].filter(el=>!el.disabled&&el.getClientRects().length);const first=controls[0],last=controls.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}}});
  modal.querySelector('.studio-close').focus();
  return {modal,close,signal:controller.signal,isClosed:()=>closed,query:selector=>modal.querySelector(selector),setBusy:value=>{if(closed)return;busy=value;modal.querySelector('.studio-close').disabled=value},onCleanup:fn=>{cleanup=fn;if(closed)cleanup()},message:(text,error=false)=>{if(closed)return;const box=modal.querySelector('.studio-message');box.textContent=text;box.classList.toggle('error',error)}};
}

async function loadImage(url){const image=new Image();image.crossOrigin='anonymous';image.src=url;try{await image.decode()}catch{throw new Error('Não foi possível abrir esta arte. Confira a conexão e tente novamente.')}return image}

export function createArtStudio(ctx){
  const {supabase}=ctx,owner=()=>ctx.accountOwnerId(),user=()=>ctx.state().session?.user?.id;
  const assertActive=signal=>{if(signal?.aborted)throw new DOMException('Operação interrompida ao fechar o estúdio ou trocar a conta.','AbortError')};
  const getProfile=async asset=>{const {data,error}=await supabase.from('z19p_asset_print_profiles').select('*').eq('asset_id',asset.id).maybeSingle();if(error)throw error;return data};
  const assetUrl=asset=>ctx.publicUrl(asset.processed_path||asset.original_path);

  async function openMockup(asset,options={}){
    if(!asset||asset.asset_type!=='arte')return;
    const dialog=mountDialog('Veja sua arte na peça',asset.name,`<div class="studio-loading">Preparando o provador…</div>`,'<span>Escala física ajustável • frente, costas e mangas</span>','shirt-studio');
    try{
      const [profile,image]=await Promise.all([getProfile(asset),loadImage(assetUrl(asset))]);if(!dialog.modal.isConnected)return;
      const ratio=image.naturalWidth/image.naturalHeight,placement=asset.metadata?.shirt_placement||{},state={side:placement.side||'front',color:placement.color||'black',shirtWidth:placement.shirt_width_cm||54,shirtLength:placement.shirt_length_cm||74,sleeveWidth:placement.sleeve_width_cm||18,sleeveLength:placement.sleeve_length_cm||22,width:Number(profile?.default_width_cm)||Math.min(28,image.naturalWidth/300*2.54),x:placement.x_cm??27,y:placement.y_cm??25};
      if(!profile)state.width=Math.max(1,state.width);let zoom=1,drag=null,observer;const positions={...(placement.positions||{})};const isSleeve=()=>state.side==='left'||state.side==='right';const surface=()=>isSleeve()?{width:state.sleeveWidth,length:state.sleeveLength,fraction:.23,heightFraction:.32,left:state.side==='left'?.435:.335,top:.15}:{width:state.shirtWidth,length:state.shirtLength,fraction:.59,heightFraction:.89,left:.205,top:.05};
      if(isSleeve()&&!positions[state.side]){state.x=state.sleeveWidth/2;state.y=state.sleeveLength/2}
      dialog.query('.studio-loading').outerHTML=`<div class="shirt-studio-layout"><div class="shirt-visual"><div class="shirt-top-controls"><div class="studio-segment" aria-label="Lado da camisa"><button data-side="front" class="active">Frente</button><button data-side="back">Costas</button><button data-side="left">Manga esq.</button><button data-side="right">Manga dir.</button></div><div class="shirt-colors" aria-label="Cor da camisa"><button class="black active" data-color="black" aria-label="Camisa preta"></button><button class="white" data-color="white" aria-label="Camisa branca"></button></div></div><div class="shirt-stage-viewport"><div class="shirt-stage"><div class="shirt-surface"></div><div class="shirt-body-guide"></div><div class="shirt-art" tabindex="0" role="group" aria-label="Arte na camisa; use as setas para mover"><img src="${escape(assetUrl(asset))}" alt="${escape(asset.name)}" draggable="false"><span class="shirt-art-size"></span><button class="shirt-resize" aria-label="Arraste para alterar o tamanho">↘</button></div><div class="shirt-width-ruler"></div></div></div><div class="shirt-visual-help"><span>Arraste a arte • puxe o canto para redimensionar</span><label>Zoom <input class="shirt-zoom" type="range" min="100" max="180" value="100" aria-label="Zoom do provador"></label></div></div><aside class="shirt-settings"><span class="studio-eyebrow">TAMANHO DA ESTAMPA</span><div class="shirt-dimensions"><label>Largura <span>cm</span><input id="shirtArtWidth" inputmode="decimal"></label><span>×</span><label>Altura <span>cm</span><input id="shirtArtHeight" inputmode="decimal"></label></div><p class="studio-note">Proporção original preservada ao editar qualquer medida.</p><div class="shirt-presets"><button data-size="9">Peito · 9 cm</button><button data-size="20">Média · 20 cm</button><button data-size="28">Grande · 28 cm</button></div><button class="studio-secondary" id="centerShirtArt">Centralizar arte</button><div class="studio-divider"></div><span class="studio-eyebrow">MEDIDA REAL DA CAMISETA</span><div class="shirt-measure-fields"><label><span id="shirtMeasureWidthLabel">Largura do corpo (cm)</span><input id="shirtBodyWidth" inputmode="decimal" value="${decimal(state.shirtWidth)}"></label><label><span id="shirtMeasureLengthLabel">Ombro até a barra (cm)</span><input id="shirtBodyLength" inputmode="decimal" value="${decimal(state.shirtLength)}"></label></div><p class="studio-note" id="shirtMeasureNote">Meça a peça estendida, de uma lateral à outra. A simulação usa estas medidas; o caimento no corpo varia.</p><div class="shirt-scale-status"></div><label class="studio-check"><input id="shirtHalftone" type="checkbox" ${profile?.halftone?'checked':''}>Esta arte é halftone</label><label class="studio-check"><input id="shirtReady" type="checkbox" ${profile?.ready_for_print?'checked':''}>Liberar esta arte no Montar Filme</label></aside></div>`;
      dialog.query('.art-studio-footer').innerHTML=`<div><b class="shirt-footer-size"></b><small>${profile?'A medida cadastrada só muda ao salvar.':'Defina a medida e escolha se deseja liberar para impressão.'}</small></div><button class="studio-primary" id="saveShirtSize">Salvar tamanho da arte</button>`;
      dialog.query('.shirt-settings').insertAdjacentHTML('afterbegin','<button class="studio-primary open-complete-garment">Montar camiseta completa ↗</button><p class="studio-note">Várias estampas, normal ou oversized, off-white e apresentação para o cliente.</p><div class="studio-divider"></div>');
      dialog.query('.open-complete-garment').onclick=()=>{dialog.close();openGarmentComposer(ctx,asset,{...options,width:state.width,side:state.side,placement:{...state}})};
      const stage=dialog.query('.shirt-stage'),art=dialog.query('.shirt-art'),widthInput=dialog.query('#shirtArtWidth'),heightInput=dialog.query('#shirtArtHeight');
      const update=(syncInputs=true)=>{
        const face=surface();stage.style.aspectRatio=`1 / ${(face.length/face.width)*(face.fraction/face.heightFraction)}`;stage.style.width=`${zoom*100}%`;stage.style.maxWidth='none';
        const size=stage.clientWidth,scale=size*face.fraction/face.width,height=state.width/ratio,left=face.left*size,top=face.top*stage.clientHeight;
        art.style.width=`${state.width*scale}px`;art.style.height=`${height*scale}px`;art.style.left=`${left+state.x*scale}px`;art.style.top=`${top+state.y*scale}px`;
        const backdrop=dialog.query('.shirt-surface');backdrop.style.backgroundImage=`url('./assets/${isSleeve()?'shirt-sleeves-atlas.png':'shirt-studio-atlas.png'}')`;backdrop.style.backgroundPosition=`${state.side==='front'||state.side==='left'?'0':'100'}% ${state.color==='black'?'0':'100'}%`;
        dialog.modal.querySelectorAll('[data-side]').forEach(b=>b.classList.toggle('active',b.dataset.side===state.side));dialog.modal.querySelectorAll('[data-color]').forEach(b=>b.classList.toggle('active',b.dataset.color===state.color));
        if(syncInputs){widthInput.value=decimal(state.width);heightInput.value=decimal(height)}
        const dimensions=`${decimal(state.width)} × ${decimal(height)} cm`;dialog.query('.shirt-art-size').textContent=dimensions;dialog.query('.shirt-footer-size').textContent=dimensions;
        dialog.query('.shirt-width-ruler').textContent=`← ${isSleeve()?'face externa da manga':'corpo da camiseta'}: ${decimal(face.width)} cm →`;
        const outside=state.x-state.width/2<0||state.x+state.width/2>face.width||state.y-height/2<0||state.y+height/2>face.length;
        dialog.query('.shirt-scale-status').textContent=outside?'Parte da arte está fora da superfície medida. Ajuste a posição ou o tamanho.':`Escala: arte de ${decimal(state.width)} cm em uma peça de ${decimal(face.width)} cm.`;dialog.query('.shirt-scale-status').classList.toggle('warning',outside);
      };
      widthInput.oninput=()=>{const value=number(widthInput.value);if(value>0&&value<=200){state.width=value;heightInput.value=decimal(value/ratio);update(false)}};
      heightInput.oninput=()=>{const value=number(heightInput.value);if(value>0&&value*ratio<=200){state.width=value*ratio;widthInput.value=decimal(state.width);update(false)}};
      dialog.modal.querySelectorAll('[data-size]').forEach(b=>b.onclick=()=>{state.width=Number(b.dataset.size);update()});
      const syncMeasurements=()=>{const face=surface();dialog.query('#shirtBodyWidth').value=decimal(face.width);dialog.query('#shirtBodyLength').value=decimal(face.length);dialog.query('#shirtMeasureWidthLabel').textContent=isSleeve()?'Largura externa da manga (cm)':'Largura do corpo (cm)';dialog.query('#shirtMeasureLengthLabel').textContent=isSleeve()?'Costura até a barra (cm)':'Ombro até a barra (cm)';dialog.query('#shirtMeasureNote').textContent=isSleeve()?'Esquerda/direita de quem veste. Meça a face externa da manga estendida; a curvatura real pode mudar a aparência.':'Meça a peça estendida, de uma lateral à outra. A simulação usa estas medidas; o caimento no corpo varia.'};
      dialog.modal.querySelectorAll('[data-side]').forEach(b=>b.onclick=()=>{positions[state.side]={x:state.x,y:state.y};state.side=b.dataset.side;const face=surface(),position=positions[state.side];state.x=position?.x??face.width/2;state.y=position?.y??face.length*(isSleeve()?.5:.36);syncMeasurements();stage.classList.remove('flipping');void stage.offsetWidth;stage.classList.add('flipping');update()});
      dialog.modal.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>{state.color=b.dataset.color;update()});
      for(const [id,bodyKey,sleeveKey,min,max] of [['#shirtBodyWidth','shirtWidth','sleeveWidth',20,120],['#shirtBodyLength','shirtLength','sleeveLength',25,150]])dialog.query(id).oninput=e=>{const value=number(e.target.value);if(value>=(isSleeve()?5:min)&&value<=(isSleeve()?60:max)){state[isSleeve()?sleeveKey:bodyKey]=value;update()}};
