export const GLYPH_KEYS='ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'.split('');
export function normalizeHexColor(value){const raw=String(value||'').trim().toUpperCase();return /^#[0-9A-F]{6}$/.test(raw)?raw:null;}
export function suggestGlyphKey(filename){const stem=String(filename||'').replace(/\.svg$/i,'').trim().toUpperCase();return /^[A-Z0-9]$/.test(stem)?stem:'';}
export function validateGlyphAssignments(drafts){
  const mapped=new Map();
  for(const draft of drafts){if(!draft.key)continue;if(!GLYPH_KEYS.includes(draft.key))throw new Error(`Selecione uma letra A–Z ou número 0–9 para ${draft.name}.`);if(draft.ext!=='svg'||!draft.markup)throw new Error(`${draft.name}: o caractere precisa de um SVG válido.`);if(mapped.has(draft.key))throw new Error(`Há dois arquivos para “${draft.key}”. Escolha somente um antes de salvar.`);mapped.set(draft.key,draft);}
