    }catch(error){errorOutput.textContent=`${error.message||'Falha ao salvar.'} A personalização continua em preparação. Os arquivos já guardados aparecem na lista; você pode tentar salvar novamente.`;drawDrafts();drawExisting();}
    finally{busy=false;modal.querySelectorAll('button,select,input').forEach(control=>control.disabled=false);button.textContent='Salvar preparação'}
  };
  q('#workingCustomizationSource').onchange=event=>{selectedWorkingId=event.target.value;showWorking()};q('[data-save-preparer]').onclick=save;
  modal.querySelectorAll('[data-close-preparer]').forEach(button=>button.onclick=close);input.onchange=()=>addFiles([...input.files]);q('.preparer-dropzone').onclick=()=>{if(!busy)input.click()};q('.preparer-dropzone').onkeydown=event=>{if(['Enter',' '].includes(event.key)){event.preventDefault();if(!busy)input.click()}};
