import {sanitizeFilmDraft,filmDraftKey,FILM_DRAFT_MAX_BYTES} from './film-draft.js?v=2.17.3';
export function createCloudFilmDraftStore({supabase,owner,user,legacyStorage,now=()=>new Date().toISOString()}={}){
  const account=String(owner()||''),userId=String(user()||'');let revision,legacyText=null,legacyComplete=true,busy=false;
  const guard=()=>{if(!account||!userId||String(owner()||'')!==account||String(user()||'')!==userId){const error=new Error('A conta ou usuário mudou. Reabra o filme.');error.code='DRAFT_ACCOUNT_CHANGED';throw error}};
  const errorResult=error=>({ok:false,mode:'cloud',code:error?.code||'DRAFT_FAILURE',warning:['42P01','PGRST205'].includes(error?.code)?'O rascunho na nuvem ainda não está habilitado. A montagem aberta não foi salva; mantenha a aba aberta e tente novamente.':error?.message||'Não foi possível confirmar o rascunho na nuvem. Mantenha a aba aberta.'});
  const prepare=input=>{const result=sanitizeFilmDraft({version:1,ownerId:account,savedAt:now(),items:input.items,settings:input.settings,layout:input.layout||null});if(result.data.items.length!==input.items?.length)throw new Error('Há itens inválidos. O rascunho anterior na nuvem foi preservado.');const text=JSON.stringify(result.data);if(new TextEncoder().encode(text).length>FILM_DRAFT_MAX_BYTES)throw new Error('A montagem ultrapassa 8 MB; o rascunho anterior foi preservado.');return result};
  function legacy(){try{const storage=typeof legacyStorage==='function'?legacyStorage():legacyStorage,text=storage?.getItem?.(filmDraftKey(account));if(!text)return null;if(new TextEncoder().encode(text).length>FILM_DRAFT_MAX_BYTES)throw new Error('O rascunho antigo ultrapassa 8 MB.');const parsed=JSON.parse(text);if(parsed.ownerId!==account)throw new Error('O rascunho antigo pertence a outra conta.');const result=sanitizeFilmDraft(parsed);legacyText=text;legacyComplete=result.data.items.length===parsed.items?.length;return {...result,rawAvailable:true};}catch(error){return {data:null,warnings:['Rascunho antigo preservado, mas não pôde ser lido: '+error.message]}}}
  function conflict(){return Object.assign(new Error('O filme foi alterado em outra aba ou aparelho. Sua montagem aberta foi preservada. Escolha carregar a versão da nuvem ou substituir explicitamente pela montagem aberta.'),{code:'DRAFT_CONFLICT'})}
  return {
    async load(){try{guard();const result=await supabase.from('z19p_film_drafts').select('*').eq('owner_id',account).eq('user_id',userId).maybeSingle();guard();if(result.error)throw result.error;let data=null,warnings=[];if(result.data){if(result.data.owner_id!==account||result.data.user_id!==userId||result.data.data?.ownerId!==account||!Number.isSafeInteger(Number(result.data.revision))||Number(result.data.revision)<1)throw new Error('O rascunho retornado não corresponde à conta ou está inválido.');const checked=prepare(result.data.data);data=checked.data;warnings=checked.warnings;data.savedAt=result.data.updated_at;revision=Number(result.data.revision);}else revision=null;return {ok:true,mode:'cloud',data,revision,savedAt:result.data?.updated_at||null,warnings,legacy:legacy()};}catch(error){return {...errorResult(error),legacy:error?.code==='DRAFT_ACCOUNT_CHANGED'?null:legacy()}}},
    async save(input,{migrateLegacy=false}={}){let started=false;try{guard();if(busy)throw Object.assign(new Error('Aguarde a gravação do rascunho em andamento.'),{code:'DRAFT_BUSY'});if(revision===undefined)throw new Error('Carregue a versão da nuvem antes de salvar. A montagem aberta foi preservada.');const prepared=prepare(input),expected=revision;busy=true;started=true;let query=expected===null?supabase.from('z19p_film_drafts').insert({owner_id:account,user_id:userId,data:prepared.data}):supabase.from('z19p_film_drafts').update({data:prepared.data}).eq('owner_id',account).eq('user_id',userId).eq('revision',expected);const result=await query.select().maybeSingle();guard();if(result.error){if(['23505','PGRST116'].includes(result.error.code))throw conflict();throw result.error}if(!result.data)throw conflict();if(result.data.owner_id!==account||result.data.user_id!==userId||Number(result.data.revision)!==(expected===null?1:expected+1))throw new Error('Não foi possível confirmar a revisão salva. Recarregue a nuvem antes de tentar novamente.');revision=Number(result.data.revision);const warnings=[...prepared.warnings];let legacyPreserved=false;if(migrateLegacy&&legacyText&&!legacyComplete){legacyPreserved=true;warnings.push('Itens válidos confirmados na nuvem. A cópia antiga contém itens inválidos e foi preservada para revisão.')}else if(migrateLegacy&&legacyText){try{const storage=typeof legacyStorage==='function'?legacyStorage():legacyStorage;if(storage?.getItem?.(filmDraftKey(account))===legacyText){storage.removeItem(filmDraftKey(account));legacyText=null;}else{legacyPreserved=true;warnings.push('A cópia antiga desta aba mudou durante a migração e foi preservada.')}}catch{legacyPreserved=true;warnings.push('O filme está na nuvem, mas a cópia antiga desta aba não pôde ser removida.')}}return {ok:true,mode:'cloud',revision,savedAt:result.data.updated_at,warnings,legacyPreserved};}catch(error){return errorResult(error)}finally{if(started)busy=false}},
    get revision(){return revision},get busy(){return busy}
  };
}

