.fp-image{position:relative;display:grid;place-items:center;overflow:hidden;aspect-ratio:1.25;background-color:#d0d0d2;background-image:linear-gradient(45deg,#e0e0e2 25%,transparent 25%),linear-gradient(-45deg,#e0e0e2 25%,transparent 25%),linear-gradient(45deg,transparent 75%,#e0e0e2 75%),linear-gradient(-45deg,transparent 75%,#e0e0e2 75%);background-size:18px 18px;background-position:0 0,0 9px,9px -9px,-9px 0}
.fp-image img{display:block;width:100%;height:100%;min-height:0;object-fit:contain;padding:20px;filter:drop-shadow(0 2px 3px #0002);transition:transform .2s}
.fp-preview-button:hover .fp-image img{transform:scale(1.04)}
.fp-image.is-error img{display:none}
.fp-image-placeholder{display:none;position:absolute;inset:0;place-content:center;justify-items:center;gap:9px;background:#26262bdc;color:#ccc6d2;font-size:10px}
.fp-image-placeholder svg{width:30px;height:30px;opacity:.65}
.fp-image.is-loading .fp-image-placeholder,.fp-image.is-error .fp-image-placeholder{display:grid}
.fp-image.is-loading img{opacity:0}
.fp-check{position:absolute;right:10px;top:10px;display:grid;place-items:center;width:28px;height:28px;border-radius:9px;border:1px solid #7c7d81;background:#18181edb;box-shadow:0 3px 9px #0002;color:#fff;font-size:19px;font-weight:750}
.fp-art-card.is-selected .fp-check{background:var(--fp-accent);border-color:var(--fp-accent);color:#1a0b04}
.fp-halftone{position:absolute;bottom:9px;left:10px;border-radius:6px;padding:4px 7px;background:#17151ad6;border:1px solid #6c5d7180;color:#f2e1f5;font-size:8px;letter-spacing:.03em;font-weight:700}
.fp-art-copy{padding:14px}
.fp-art-copy>small{display:block;color:#a1a0ac;font-size:9px;font-weight:650;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
