.fp-art-location{color:#81808b;font-size:9px;margin:0 0 13px;min-height:13px;white-space:nowrap;text-overflow:ellipsis;overflow:hidden}
.fp-size-line{display:flex;align-items:center;justify-content:space-between;gap:7px;flex-wrap:wrap}
.fp-size-line strong{color:#fbc6a8;font-size:17px;font-weight:800;letter-spacing:-.04em;white-space:nowrap}
.fp-size-line strong>span{color:#947b6f;font-size:13px;font-weight:500;margin:0 2px}
